def archived_to_paused(apps, schema_editor):
    # Until now "archived" was what Pause did (the list called it "Paused" and Resume
    # turned it back on), so every archived workflow is really a paused one.
    Workflow = apps.get_model("automation", "Workflow")
    Workflow.objects.filter(status="archived").update(status="paused")


def paused_to_archived(apps, schema_editor):
    Workflow = apps.get_model("automation", "Workflow")
    Workflow.objects.filter(status="paused").update(status="archived")


